dtsPropsFor.Button:
/** Visual style. */
variant?: "primary" | "secondary" | "ghost" | "icon";
size?: "sm" | "md" | "lg";
/** Stretch to full width (handy on mobile). */
block?: boolean;
className?: string;
children: React.ReactNode;
/** When set, renders an <a> (link) instead of <button>. */
href?: string;
target?: string;
rel?: string;
type?: "button" | "submit" | "reset";
disabled?: boolean;
onClick?: React.MouseEventHandler;
"aria-label"?: string;

dtsPropsFor.SegmentedControl:
value: string;
onChange: (value: string) => void;
options: { value: string; label: React.ReactNode }[];
ariaLabel: string;
/** "md" — filters/sort; "sm" — compact (e.g. language switch). */
size?: "sm" | "md";

dtsPropsFor.VerdictBadges:
counts: {
  confirmed: number;
  contradicted: number;
  unverified: number;
  total: number;
  coverage_pct: number;
};
/** "full" — answer headline + ratio bar + legend (report header); "compact" — inline pills (table rows). */
variant?: "full" | "compact";

dtsPropsFor.PipelineProgress:
steps: {
  id: string;
  name: string;
  status: "pending" | "active" | "done" | "error";
  message?: string;
}[];

dtsPropsFor.ReportViewer:
/** Markdown report body. */
content: string;
/** Original filename for the .md download (defaults to "report.md"). */
downloadName?: string;
/** When set, a "copy link" button copies the current page URL. */
reportId?: string;
/** Optional muted notice above the toolbar (e.g. machine-translation disclaimer). */
note?: string;

dtsPropsFor.AnimatedNumber:
/** Target number; counts up from 0. */
to: number;
/** Suffix after the number (e.g. "+"). */
suffix?: string;
/** Animation duration, ms. */
duration?: number;
